const body = $input.first().json.body || $input.first().json;
const text = String(body.message || body.chatQuery || body.taskTitle || body.taskDescription || '').toLowerCase();
let agentCode = (body.agentCode || '').toUpperCase();

if (!agentCode || agentCode === 'CEO' || agentCode === 'ORCHESTRATOR') {
  if (text.includes('github') || text.includes('repo') || text.includes('rama') || text.includes('código') || text.includes('pr') || text.includes('commit') || text.includes('test') || text.includes('sam')) {
    agentCode = 'COWORKER';
  } else if (text.includes('correo') || text.includes('email') || text.includes('gmail') || text.includes('calendar') || text.includes('agenda') || text.includes('drive') || text.includes('minuta') || text.includes('taylor') || text.includes('secretaria')) {
    agentCode = 'ASSISTANT';
  } else if (text.includes('manager') || text.includes('jordan') || text.includes('salud') || text.includes('sentry') || text.includes('postgres') || text.includes('reporte') || text.includes('noche') || text.includes('sueño') || text.includes('auditor')) {
    agentCode = 'MANAGER';
  } else {
    agentCode = 'COWORKER';
  }
}

let assignedWorkflow = '';
let targetWebhook = '';

if (agentCode === 'ASSISTANT') {
  assignedWorkflow = 'Sleeply - Secretary Gmail & Calendar Manager';
  targetWebhook = 'https://n8n-dev1.auto-node.tech/webhook/sleeply-secretary-agent';
} else if (agentCode === 'MANAGER') {
  assignedWorkflow = 'Sleeply - Manager Nightly Monitor & Report';
  targetWebhook = 'https://n8n-dev1.auto-node.tech/webhook/sleeply-manager-agent';
} else {
  assignedWorkflow = 'Sleeply - Co-worker GitHub & Code Executor';
  targetWebhook = 'https://n8n-dev1.auto-node.tech/webhook/sleeply-coworker-agent';
}

return [{
  json: {
    ...body,
    orchestrated: true,
    agentCode,
    taskTitle: body.taskTitle || (body.message ? 'Instruccion de Chat Orquestada' : 'Tarea Orquestada Sleeply'),
    taskDescription: body.taskDescription || body.message || 'Procesamiento de rol automatizado con Meta AI',
    operatingMode: body.operatingMode || 'awake',
    assignedWorkflow,
    targetWebhook,
    timestamp: new Date().toISOString()
  }
}];
